export const MARKETS=[{id:'vidya',name:'Vidya Vikas Market',short:'Vidya Vikas',stall:'A-12',hours:'6:00 AM–12:00 PM'},{id:'gangapur',name:'Gangapur Road Market',short:'Gangapur Road',stall:'B-05',hours:'7:00 AM–1:00 PM'},{id:'mandai',name:'Nashik Bhaji Mandai',short:'Nashik Bhaji Mandai',stall:'D-08',hours:'5:30 AM–11:00 AM',closed:true}];
export const PRODUCTS=[{id:'tomato',name:'Tomato',unit:'kg',rate:25,step:.25},{id:'coriander',name:'Coriander Bunch',unit:'bunch',rate:10,step:1,guidance:{rate:12,min:10,max:12}},{id:'potato',name:'Potato',unit:'kg',rate:18,step:.25}];
export const clone=x=>JSON.parse(JSON.stringify(x));
export const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
export const money=n=>'₹'+Number(n).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
export const amount=i=>Math.round((Number(i.qty)*Number(i.rate)+Number.EPSILON)*100);
export const total=items=>items.reduce((v,i)=>v+amount(i),0)/100;
export const market=id=>MARKETS.find(m=>m.id===id);
export const product=id=>PRODUCTS.find(p=>p.id===id);
export function line(productId,qty,rate,id=uid(),source='manual'){const p=product(productId);if(!p)throw Error('Select a product.');return {id,productId,name:p.name,unit:p.unit,qty:Number(qty),rate:Number(rate),source};}
export function emptyDraft(marketId){return {id:uid(),marketId,items:[],phone:'',revision:0};}
export function seed(){const mk=(id,marketId,time,receipt,items)=>({id:'FB-2026-'+id,marketId,date:'2026-09-16',time,phone:receipt==='not_requested'?'':'9876543210',receipt,items,requestId:'sample-'+id});return {schema:1,selected:null,draft:null,editor:null,saveRequest:null,lastSaved:null,sequence:43,bills:[mk('042','vidya','9:45 AM','sent',[line('tomato',2.5,25,'042a'),line('coriander',2,10,'042b'),line('potato',3,20,'042c')]),mk('041','vidya','9:15 AM','not_requested',[line('tomato',2,25,'041a'),line('coriander',4,13,'041b'),line('potato',2,18,'041c')]),mk('040','gangapur','8:45 AM','failed',[line('tomato',4,25,'040a'),line('potato',2,18,'040b')])]};}
export function locked(s){return ['pending','unknown'].includes(s.saveRequest?.status);}
function writable(s){if(locked(s))throw Error('Check the current save result before changing this bill.');}
export function selectMarket(s,id,discard=false){writable(s);const m=market(id);if(!m||m.closed)throw Error('This market is not open today.');if(s.draft?.marketId!==id&&(s.draft?.items.length||s.editor)&&!discard)throw Error('Confirm before discarding your current draft.');if(s.selected!==id){s.selected=id;s.draft=emptyDraft(id);s.editor=null;s.saveRequest=null;}else if(!s.draft)s.draft=emptyDraft(id);}
export function validateLine(p,qty,rate){if(!p)throw Error('Choose a product.');const q=String(qty).trim(),r=String(rate).trim();if(!/^\d+(\.\d{1,3})?$/.test(q)||+q<=0||+q>100000)throw Error('Enter a quantity greater than zero, up to 100,000.');if(p.unit!=='kg'&&!Number.isInteger(+q))throw Error('Enter a whole number of bunches.');if(!/^\d+(\.\d{1,2})?$/.test(r)||+r<=0||+r>1000000)throw Error('Enter a rate greater than zero with up to 2 decimal places.');}
export function commitLine(s,entry){writable(s);if(!s.draft||s.draft.marketId!==s.selected)throw Error('Choose a market first.');validateLine(product(entry.productId),entry.qty,entry.rate);const existing=s.draft.items.find(i=>i.id===entry.id);const l=line(entry.productId,entry.qty,entry.rate,existing?.id||uid(),entry.source||'manual');if(existing)s.draft.items[s.draft.items.indexOf(existing)]=l;else s.draft.items.push(l);s.draft.revision++;s.saveRequest=null;s.editor=null;return l;}
export function removeLine(s,id){writable(s);if(!s.draft?.items.some(i=>i.id===id))throw Error('This item is no longer in your bill.');s.draft.items=s.draft.items.filter(i=>i.id!==id);s.draft.revision++;s.saveRequest=null;}
export function phoneNumber(value){let v=String(value).replace(/[\s()-]/g,'');if(!v)return '';if(v.startsWith('+91'))v=v.slice(3);if(!/^[6-9]\d{9}$/.test(v))throw Error('Enter a valid 10-digit mobile number, or leave it blank.');return v;}
export function setPhone(s,value){writable(s);const phone=phoneNumber(value);if(!s.draft)throw Error('Start a bill first.');if(s.draft.phone!==phone){s.draft.phone=phone;s.draft.revision++;s.saveRequest=null;}return phone;}
export function beginSave(s){if(s.saveRequest&&['pending','unknown','saved'].includes(s.saveRequest.status))return s.saveRequest;if(!s.draft?.items.length)throw Error('Add a product before saving this bill.');s.draft.items.forEach(i=>validateLine(product(i.productId),i.qty,i.rate));phoneNumber(s.draft.phone);if(s.saveRequest?.status==='failed'&&s.saveRequest.snapshot.revision===s.draft.revision){s.saveRequest.status='pending';return s.saveRequest;}s.saveRequest={id:uid(),status:'pending',snapshot:clone(s.draft)};return s.saveRequest;}
export function finishSave(s,requestId){const req=s.saveRequest;if(!req||req.id!==requestId)throw Error('The save attempt could not be found.');let bill=s.bills.find(b=>b.requestId===requestId);if(!bill){const d=req.snapshot;bill={id:'FB-2026-'+String(s.sequence++).padStart(3,'0'),requestId,marketId:d.marketId,items:clone(d.items),phone:d.phone,date:'2026-09-16',time:sampleTime(s.sequence),receipt:d.phone?'ready':'not_requested'};s.bills.unshift(bill);}req.status='saved';s.lastSaved=bill.id;if(s.draft?.id===req.snapshot.id)s.draft=null;s.editor=null;return bill;}
function sampleTime(n){const mins=10*60+32+Math.max(0,n-44);return `${Math.floor(mins/60)}:${String(mins%60).padStart(2,'0')} AM`;}
export function saveOutcome(s,outcome){if(!s.saveRequest||s.saveRequest.status!=='pending')throw Error('No save is in progress.');if(outcome==='failed'||outcome==='unknown'){s.saveRequest.status=outcome;return null;}return finishSave(s,s.saveRequest.id);}
export function nextBill(s){writable(s);if(s.draft?.items.length)throw Error('Your current draft still has items.');if(!s.selected)throw Error('Select a market first.');s.draft=emptyDraft(s.selected);s.editor=null;s.saveRequest=null;}
export function sendReceipt(s,id){const b=s.bills.find(b=>b.id===id);if(!b)throw Error('Saved bill not found.');if(!b.phone)throw Error('No receipt was requested for this bill.');if(b.receipt==='sent'||b.receipt==='sending')return b;b.receipt='sending';return b;}
export function receiptOutcome(s,id,outcome){const b=s.bills.find(b=>b.id===id);if(!b||b.receipt!=='sending')return;b.receipt=outcome==='failed'?'failed':'sent';}
export function draftScenario(){const s=seed();selectMarket(s,'vidya');commitLine(s,{productId:'tomato',qty:3,rate:25});commitLine(s,{productId:'potato',qty:1,rate:18});s.draft.phone='9876543210';return s;}
